use vstd::prelude::*;

verus! {

/// Pointwise logical OR on sequences.
spec fn seq_logical_or(s1: Seq<bool>, s2: Seq<bool>) -> Seq<bool>
    recommends
        s1.len() == s2.len(),
{
    Seq::new(s1.len(), |i: int| s1[i] || s2[i])
}

fn logical_or(x1: Vec<bool>, x2: Vec<bool>) -> (out: Vec<bool>)
    requires
        x1@.len() == x2@.len(),
    ensures
        out@.len() == x1@.len(),
        out@ == seq_logical_or(x1@, x2@),
        forall|i: int|
            0 <= i < out@.len() ==> out@[i] == (x1@[i] || x2@[i]),
{
    assert_eq!(x1.len(), x2.len(), "Input vectors must have the same length");

    x1.into_iter()
        .zip(x2.into_iter())
        .map(|(a, b)| a || b)
        .collect()
}

} // verus!

